/**
 * guuey#2366 / #2381 — the A2UI kind across a rolling release (spec §10).
 *
 * Each `fixtures/a2ui-n1-*.json` is one N−1 claim. Its expected plan in
 * `__snapshots__/a2ui-n1-*.snap` was generated by the planner at the base sha,
 * BEFORE the a2ui kind existed, so it is the old client's face: an old kit
 * (F1, F5, F8, F9) and a new kit reading an old server (F2) must keep planning
 * exactly that.
 */
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import type { AgBlock } from "@silverprotocol/core";
import {
  threadHistoryRowsToCards,
  threadHistoryRowsToMessages,
  threadHistoryRowsToToolCalls,
  threadHistoryRowsToToolResults,
  type InvokeTurnEvent,
  type ThreadHistoryRow,
} from "@guuey/agent-client";
import { toolResultViewMount } from "@guuey/mcp-apps-host";
import { transcriptInputsFromHistory } from "../history-inputs.js";
import { newestViewKey, planTranscript } from "../plan.js";
import { calmPolicy, type TranscriptPolicy } from "../policy.js";
import type { TranscriptInputs, TranscriptMessage, TranscriptPlan } from "../types.js";
import { driveTurn } from "./drive.js";

/** A live fixture: the AgJSON stream of one turn and the user's words. */
interface StreamFixture {
  claim: string;
  userText: string;
  events: InvokeTurnEvent[];
}

/** F5: stored flat rows only. */
interface RowsFixture {
  claim: string;
  messages: TranscriptMessage[];
}

/** F2: a served history page (no carrier) and a live turn (no carrier). */
interface PageFixture extends StreamFixture {
  rows: ThreadHistoryRow[];
}

const FIXTURES = new URL("./fixtures/", import.meta.url);
const text = (name: string): string => readFileSync(new URL(name, FIXTURES), "utf8");
const stream = (name: string): StreamFixture => JSON.parse(text(name));
const rows = (name: string): RowsFixture => JSON.parse(text(name));
const page = (name: string): PageFixture => JSON.parse(text(name));

const snap = (name: string): string => `./__snapshots__/${name}.snap`;
const serialize = (plan: TranscriptPlan): string => `${JSON.stringify(plan, null, 2)}\n`;

const live = (f: StreamFixture): TranscriptInputs => driveTurn(f.events, { userText: f.userText });

/** A new kit that draws the a2ui kind (S2/S3 turn this on in their renderers). */
const renderOn = (): TranscriptPolicy => calmPolicy({ a2ui: { render: true } });

function settledInputs(messages: TranscriptMessage[]): TranscriptInputs {
  return {
    result: null,
    assistantText: "",
    status: "ready",
    statusElapsedMs: 0,
    activeTool: null,
    error: null,
    prompts: [],
    messages,
  };
}

/** The history page through the real client mapper and the real history assembler. */
function historyInputs(f: PageFixture): TranscriptInputs {
  return transcriptInputsFromHistory({
    messages: threadHistoryRowsToMessages(f.rows),
    cards: threadHistoryRowsToCards(f.rows),
    toolResults: threadHistoryRowsToToolResults(f.rows),
    toolCalls: threadHistoryRowsToToolCalls(f.rows),
  });
}

/** Every tool-result block in a live fixture's fold. */
function toolResults(inputs: TranscriptInputs): Extract<AgBlock, { type: "tool-result" }>[] {
  return (inputs.result?.messages ?? []).flatMap((m) =>
    m.content.filter((b): b is Extract<AgBlock, { type: "tool-result" }> => b.type === "tool-result"),
  );
}

const OLD_CLIENT_LIVE = ["a2ui-n1-old-client-live", "a2ui-n1-old-client-uidata", "a2ui-n1-old-client-json-render"] as const;

describe("guuey#2381 — A2UI N−1 fixtures (spec §10)", () => {
  for (const name of OLD_CLIENT_LIVE) {
    it(`${name}: the old face — a tool row with a JSON preview, no view item, no mount`, async () => {
      const inputs = live(stream(`${name}.json`));
      for (const block of toolResults(inputs)) expect(toolResultViewMount(block), name).toBeUndefined();
      const plan = planTranscript(inputs, calmPolicy());
      expect(plan.views).toEqual([]);
      expect(newestViewKey(inputs)).toBeUndefined();
      const tool = plan.items.find((i) => i.kind === "tool");
      expect(tool?.kind === "tool" ? tool.result?.kind : undefined).toBe("data-result");
      await expect(serialize(plan)).toMatchFileSnapshot(snap(name));
    });
  }

  it("a2ui-n1-old-client-action-row: an action row is the user's own plain text", async () => {
    const plan = planTranscript(settledInputs(rows("a2ui-n1-old-client-action-row.json").messages), calmPolicy());
    const users = plan.items.filter((i) => i.kind === "user");
    expect(users).toHaveLength(2);
    const action = users[1];
    expect(action?.kind === "user" ? action.text : undefined).toContain("<guuey_a2ui_action");
    expect(action?.kind === "user" ? action.directive : undefined).toBe(false);
    await expect(serialize(plan)).toMatchFileSnapshot(snap("a2ui-n1-old-client-action-row"));
  });

  it("a2ui-n1-new-client-old-server: a history page and a live turn with no carrier", async () => {
    const f = page("a2ui-n1-new-client-old-server.json");
    await expect(serialize(planTranscript(historyInputs(f), calmPolicy()))).toMatchFileSnapshot(
      snap("a2ui-n1-new-client-old-server.history"),
    );
    await expect(serialize(planTranscript(live(f), calmPolicy()))).toMatchFileSnapshot(
      snap("a2ui-n1-new-client-old-server.live"),
    );
  });
});

describe("guuey#2381 — the same fixtures on a kit that draws the a2ui kind", () => {
  it("F2: a page and a turn with no carrier plan byte-identically to the base snapshots", async () => {
    const f = page("a2ui-n1-new-client-old-server.json");
    await expect(serialize(planTranscript(historyInputs(f), renderOn()))).toMatchFileSnapshot(
      snap("a2ui-n1-new-client-old-server.history"),
    );
    await expect(serialize(planTranscript(live(f), renderOn()))).toMatchFileSnapshot(
      snap("a2ui-n1-new-client-old-server.live"),
    );
  });

  it("F5: an action row is still the user's plain text (the action turn is S4)", async () => {
    const plan = planTranscript(settledInputs(rows("a2ui-n1-old-client-action-row.json").messages), renderOn());
    await expect(serialize(plan)).toMatchFileSnapshot(snap("a2ui-n1-old-client-action-row"));
  });

  it("F9: a json-render carrier keeps the old face byte-identically (the adapter is S5)", async () => {
    const plan = planTranscript(live(stream("a2ui-n1-old-client-json-render.json")), renderOn());
    await expect(serialize(plan)).toMatchFileSnapshot(snap("a2ui-n1-old-client-json-render"));
  });

  for (const name of ["a2ui-n1-old-client-live", "a2ui-n1-old-client-uidata"] as const) {
    it(`${name}: a new kit draws the carrier natively, the tool row folded into its chrome`, () => {
      const plan = planTranscript(live(stream(`${name}.json`)), renderOn());
      const item = plan.items.find((i) => i.kind === "a2ui");
      expect(item).toMatchObject({ key: "a2ui.call-booking.booking-1", phase: "open", origin: "live" });
      const tool = plan.items.find((i) => i.kind === "tool");
      expect(tool).toMatchObject({ result: null, attribution: true });
      expect(plan.views).toEqual([]);
    });
  }
});
